use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    var total = 0;
    var has_frame = true;
    var frame_opt = relay.feed.next_frame();
    while has_frame {
        match frame_opt {
            Some(frame) => {
                let decoded = relay.feed.decode(frame: frame);
                total = total + match decoded {
                    Some(value) => value,
                    None => 0,
                };
                frame_opt = relay.feed.next_frame();
            },
            None => {
                has_frame = false;
            },
        };
    }
    relay.feed.emit(total: total, io: io)?;
    return Ok(unit);
}

use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = relay.feed.frames();
    var total = 0;
    var i = 0;
    while i < frames.len() {
        let frame = match frames.get(index: i) {
            Some(f) => f,
            None => "",
        };
        let decoded = match relay.feed.decode(frame: frame) {
            Ok(value) => value,
            Err(_) => 0,
        };
        total = total + decoded;
        i = i + 1;
    }
    relay.feed.emit(io: io, total: total)?;
    return Ok(unit);
}

use galley.kitchen;

use galley.menu;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let dishes = galley.menu.board();
    var i = 0;
    while i < dishes.len() {
        if i > 0 {
            io.write(text: ";")?;
        }
        let served = match dishes.get(index: i) {
            Some(dish) => galley.kitchen.serve(io: io, dish: dish),
            None => Ok(unit),
        };
        served?;
        i = i + 1;
    }
    return Ok(unit);
}

use harbor.signal;

fn signal_text(signal: Signal) -> String {
    match signal {
        Calm => "calm",
        Gale(speed) => "gale:".concat(other: speed.to_text()),
        Fog(density) => "fog:".concat(other: density),
    }
}

