use stable.herd.{lineup, feed};
use stable.ledger.{entry};

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let ponies = lineup();
    var out = "";
    var sep = "";
    var i = 0;
    while i < ponies.len() {
        let fed = feed(pony: ponies.get(i), scoops: 3);
        let piece = entry(pony: fed);
        out = out.concat(other: sep).concat(other: piece);
        sep = ",";
        i = i + 1;
    }
    io.write(text: out)?;
    return Ok(unit);
}

