use mill.stock;
use mill.rules;

fn lines() -> String {
    let planks = stock.inventory();
    var out = "";
    var i = 0;
    var started = false;
    while i < planks.len() {
        let plank = planks.get(i);
        if rules.keep(plank) {
            let label = rules.label(plank);
            if started {
                out = out.concat(other: ",").concat(other: label);
            } else {
                out = label;
                started = true;
            }
        }
        i = i + 1;
    }
    out
}

